mapper.select:
SELECT p.`product_id`, p.`quote_date`, p.`retail_price`, p.`distributor1_price`, p.`distributor2_price` FROM `quote_price_history` p JOIN ( SELECT `product_id`, MAX(`quote_date`) AS `max_date` FROM `quote_price_history` WHERE `product_id` IN
#{productId}
GROUP BY `product_id` ) t ON p.`product_id` = t.`product_id` AND p.`quote_date` = t.`max_date`
